macros.command:
let params =
    [{
        filterType: "transform",
        filterId: "dodgeStance",
        padding: 50,
        animated:
        {
            translationX:
            {
                animType: "sinOscillation",
                val1: -0.012,
                val2: +0.012,
                loopDuration: 30000,
            },
            translationY:
            {
                animType: "cosOscillation",
                val1: -0.012,
                val2: +0.012,
                loopDuration: 30000,
            }
        }
    }];

TokenMagic.addUpdateFiltersOnSelected(params);

let params =
[{
    filterType: "shadow",
    filterId: "myShadow",
    rotation: 0,
    blur: 2,
    quality: 5,
    distance: 20,
    alpha: 0.7,
    padding: 10,
    shadowOnly: false,
    color: 0x000000,
    zOrder: 6000,
    animated:
    {
        blur:     
        { 
           active: true, 
           loopDuration: 5000, 
           animType: "syncCosOscillation", 
           val1: 2, 
           val2: 4
        },
        rotation:
        {
           active: true,
           loopDuration: 5000,
           animType: "syncSinOscillation",
           val1: 33,
           val2: 37
        }
     }
}];

await TokenMagic.addUpdateFiltersOnSelected(params);

function tokenUpdate(data) {
  canvas.tokens.controlled.map(token => token.document.update({light: data}));
}

let torchAnimation = {"type": "torch", "speed": 6, "intensity": 1, "reverse": false};

let dialogEditor = new Dialog({
  title: `Token Light Picker`,
  content: `Pick the light source the selected token is holding.`,
  buttons: {
    none: {
      label: `None`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 0, "bright": 0, "angle": 360, "luminosity": 0.5});
        dialogEditor.render(true);
      }
    },
    torch: {
      label: `Torch`,
      callback: () => {
        tokenUpdate({"color": "#f65904","dim": 20, "bright": 10, "angle": 360, "luminosity": 0.5, "animation": torchAnimation});
        dialogEditor.render(true);
      },
    },
    light: {
      label: `Chemical Light`,
      callback: () => {
        tokenUpdate({"color": "#fbff00", "dim": 30, "bright": 20, "angle": 360, "luminosity": 0.5, "animation": {"type": "fog", "speed": 3, "intensity": 6, "reverse": false}});        
        dialogEditor.render(true);
      }
    },
    lamp: {
      label: `Flashlight`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 40, "bright": 25, "angle": 65, "luminosity": 0.5, "luminosity": 0.5, "animation": {"type": "fog", "speed": 1, "intensity": 1, "reverse": false}});
        dialogEditor.render(true);
      }
    },
    lamp2: {
      label: `Scary Flashlight`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 18, "bright": 5, "angle": 65, "luminosity": 0.5, "luminosity": 0.5, "animation": {"type": "fog", "speed": 5, "intensity": 1, "reverse": false}});
        dialogEditor.render(true);
      }
    }
  },

  default: "close",
  close: () => {}
});

dialogEditor.render(true);

// Macro to apply light configuration to a token in Foundry VTT
const token = canvas.tokens.controlled[0];
if (!token) {
  ui.notifications.warn("No token selected!");
  return;
}

const lightConfig = {
  "alpha": 0.5,
  "angle": 360,
  "bright": 5,
  "coloration": 7,
  "dim": 5,
  "attenuation": 0.5,
  "luminosity": 0.75,
  "saturation": 0.75,
  "contrast": 0.65,
  "shadows": 0,
  "animation": {
    "type": "fairy",
    "speed": 5,
    "intensity": 5,
    "reverse": false
  },
  "darkness": {
    "min": 0,
    "max": 1
  },
  "color": "#ffffff",
  "negative": false,
  "priority": 0
};

token.document.update({ light: lightConfig });
ui.notifications.info("Light configuration applied!");
